<script setup>
import StationLink from './StationLink.vue'
import {ref,reactive,onMounted} from 'vue'
import {api} from './api'
const emit=defineEmits(['dirty'])
function markDirty(){dirty.value=true;emit('dirty',true)}
const props=defineProps({token:String,install:Boolean,language:{type:String,default:'ru'}})
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const primaryLink=()=>status.value.configuration.peer_urls[status.value.configuration.primary_post]+(props.install?'/install':'/owner/wallet')
const value=reactive({enabled:true,bonus_mode:'shared',wash_pause_seconds:60,dry_fog_pause_seconds:300,device_types:{},shared:{enabled:false,percent:10},wash:{enabled:false,percent:10},dry_fog:{enabled:false,percent:10}})
const status=ref(null),error=ref(''),notice=ref(''),busy=ref(false),dirty=ref(false),local=ref(null)
const request=(url,options={})=>api(props.install?url.replace('/api/owner/device','/api/commissioning/device'):url,{token:props.token,...options})
async function load(){const r=await request('/api/owner/device-policy');status.value=r;const s=await request('/api/wash/state');if(r.policy)Object.assign(value,r.policy);else {const p=s.parameters.topUpBonus;value.wash_pause_seconds=s.parameters.freePauseSeconds??60;value.shared={...p};value.wash={...p};value.dry_fog={enabled:false,percent:10};value.device_types=Object.fromEntries(Object.keys(r.configuration.peer_urls).map(k=>[k,'wash']))}for(const post of Object.keys(r.configuration.peer_urls||{})){if(!(post in value.device_types))value.device_types[post]=''}local.value=await request('/api/owner/device');dirty.value=false;emit('dirty',false)}
async function run(fn){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){if(Object.values(value.device_types).some(v=>!['wash','dry_fog'].includes(v)))throw Error(tr('Выберите тип каждого поста.','Har bir post turini tanlang.','Select the type of every station.'));await request('/api/owner/device-policy',{method:'POST',body:JSON.stringify(value)});await load();notice.value=tr('Сохранено на главном и резервном. Бонусная политика применяется к новым сеансам.','Asosiy va zaxira qurilmada saqlandi. Bonus qoidalari yangi seanslarga qo‘llanadi.','Saved on primary and standby. Bonus policy applies to new sessions.')}
async function selectLocal(event){await request('/api/owner/device',{method:'POST',body:JSON.stringify({type:event.target.value,display_name:''})});for(const post of Object.keys(r.configuration.peer_urls||{})){if(!(post in value.device_types))value.device_types[post]=''}local.value=await request('/api/owner/device');notice.value=tr('Тип выбран. Установщик должен применить профиль оборудования на пустом посту.','Tur tanlandi. O‘rnatuvchi bo‘sh postda uskuna profilini qo‘llashi kerak.','Type selected. Installer must apply its hardware profile on an idle station.')}
onMounted(()=>run(load))
</script>
<template><section class="card content device-policy"><h2>{{tr('Мойка и сухой туман','Yuvish va quruq tuman','Wash and dry fog')}}</h2><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message success" role="status">{{notice}}</p><template v-if="status"><p>{{tr('Номер устройства уникален для всего объекта. Роли главного и резервного не зависят от типа.','Qurilma raqami butun obyekt uchun yagona. Asosiy va zaxira rollari turga bog‘liq emas.','Device numbers are unique across the site. Primary and standby roles are independent of type.')}}</p><p v-if="status.configuration.primary_post!==status.configuration.local_post"><StationLink :href="primaryLink()" :language="language">{{tr('Открыть настройки на главном устройстве','Asosiy qurilmada sozlamalarni ochish','Open settings on the primary device')}}</StationLink></p><form @submit.prevent="run(save)" @change="markDirty"><div class="fields"><label v-for="(_,post) in value.device_types" :key="post">{{tr('Устройство','Qurilma','Device')}} {{post}}<select :aria-label="tr('Устройство','Qurilma','Device')+' '+post" v-model="value.device_types[post]" :disabled="busy||status.configuration.primary_post!==status.configuration.local_post"><option value="" disabled>{{tr('Выберите тип','Turini tanlang','Select type')}}</option><option value="wash">{{tr('Моечный пост','Yuvish posti','Wash station')}}</option><option value="dry_fog">{{tr('Сухой туман','Quruq tuman','Dry fog')}}</option></select></label><label>{{tr('Бонусы','Bonuslar','Bonuses')}}<select :aria-label="tr('Бонусы','Bonuslar','Bonuses')" v-model="value.bonus_mode" :disabled="busy||status.configuration.primary_post!==status.configuration.local_post"><option value="shared">{{tr('Единые для всех услуг','Barcha xizmatlar uchun umumiy','Shared across services')}}</option><option value="separate">{{tr('Отдельно для мойки и тумана','Yuvish va tuman uchun alohida','Separate by device type')}}</option></select></label></div><div class="fields"><label>{{tr('Бесплатная пауза мойки, сек','Yuvish bepul pauzasi, soniya','Wash free pause, seconds')}}<input :disabled="busy||status.configuration.primary_post!==status.configuration.local_post" type="number" min="0" max="86400" v-model.number="value.wash_pause_seconds" required/></label><label>{{tr('Бесплатная пауза тумана, сек','Tuman bepul pauzasi, soniya','Dry-fog free pause, seconds')}}<input :disabled="busy||status.configuration.primary_post!==status.configuration.local_post" type="number" min="0" max="86400" v-model.number="value.dry_fog_pause_seconds" required/></label></div><div class="fields"><fieldset v-for="kind in value.bonus_mode==='shared'?['shared']:['wash','dry_fog']" :key="kind"><legend>{{kind==='shared'?tr('Общий бонус','Umumiy bonus','Shared bonus'):kind==='wash'?tr('Мойка','Yuvish','Wash'):tr('Сухой туман','Quruq tuman','Dry fog')}}</legend><label class="check"><input :disabled="busy||status.configuration.primary_post!==status.configuration.local_post" type="checkbox" v-model="value[kind].enabled"/>{{tr('Начислять бонус','Bonus berish','Award bonus')}}</label><label>%<input :disabled="busy||status.configuration.primary_post!==status.configuration.local_post" type="number" min="0" max="100" required v-model.number="value[kind].percent"/></label></fieldset></div><p>{{tr('Выданные бонусы сохраняют область использования. Переход на другой пост не обновляет бесплатную паузу.','Berilgan bonuslarning amal qilish sohasi saqlanadi. Boshqa postga o‘tish bepul pauzani yangilamaydi.','Issued bonuses retain their scope. Moving to another post does not renew free pause.')}}</p><button class="primary" :disabled="busy||!dirty||status.configuration.primary_post!==status.configuration.local_post">{{tr('Сохранить на главном и резервном','Asosiy va zaxirada saqlash','Save on primary and standby')}}</button></form><div v-if="local" class="local-device"><h3>{{tr('Тип этого устройства','Ushbu qurilma turi','This device type')}}</h3><select :aria-label="tr('Тип этого устройства','Ushbu qurilma turi','This device type')" :value="local.requested.type" :disabled="busy" @change="run(()=>selectLocal($event))"><option value="wash">{{tr('Моечный пост','Yuvish posti','Wash station')}}</option><option value="dry_fog">{{tr('Сухой туман','Quruq tuman','Dry fog')}}</option></select><p v-if="local.active_type!==local.requested.type">{{tr('Ожидает применения профиля установщиком','O‘rnatuvchi profilni qo‘llashi kutilmoqda','Waiting for installer to apply hardware profile')}}</p></div></template><button class="quiet" :disabled="busy" @click="run(load)">{{tr('Обновить','Yangilash','Refresh')}}</button></section></template>
<style scoped>.device-policy{padding:28px;margin-top:24px}.device-policy p{line-height:1.6}.device-policy label{display:flex;flex-direction:column;gap:10px}.device-policy label.check{flex-direction:row}.device-policy fieldset{border:1px solid var(--border);border-radius:8px;padding:20px}.local-device{border-top:1px solid var(--border);margin-top:24px;padding-top:24px}.local-device select{max-width:600px}</style>
